import shutil
import subprocess
import tempfile
from pathlib import Path

from django.contrib.auth import get_user_model
from django.core.files.uploadedfile import SimpleUploadedFile
from django.test import TestCase, override_settings
from django.urls import reverse

from . import services
from .models import VideoJob

User = get_user_model()
PW = "S3cure-test-pass!"
MEDIA = tempfile.mkdtemp(prefix="vox-test-media-")


def make_video(seconds=10):
    """A tiny real video with audio, generated by ffmpeg."""
    tmp = Path(tempfile.mkdtemp()) / "t.mp4"
    subprocess.run(
        [services.FFMPEG, "-y", "-nostdin", "-loglevel", "error", "-f", "lavfi", "-i", f"testsrc=size=160x120:rate=15:duration={seconds}",
         "-f", "lavfi", "-i", f"sine=frequency=440:duration={seconds}", "-c:v", "libx264", "-pix_fmt", "yuv420p",
         "-c:a", "aac", "-shortest", str(tmp)],
        check=True, capture_output=True,
    )
    return tmp.read_bytes()


@override_settings(MEDIA_ROOT=MEDIA)
class SplitterTests(TestCase):
    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        if not services.tools_available():
            raise cls.skipTest(cls, "ffmpeg not installed")
        cls.video = make_video(10)

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(MEDIA, ignore_errors=True)
        super().tearDownClass()

    def setUp(self):
        self.user = User.objects.create_user("u1", "u1@test.dev", PW)
        self.client.force_login(self.user)

    def upload(self, amount=3, unit="s", name="clip.mp4", data=None):
        # Run the worker inline so the test is deterministic.
        from unittest import mock
        with mock.patch.object(services, "start_job", side_effect=services.process_job):
            return self.client.post(reverse("splitter:index"), {
                "video": SimpleUploadedFile(name, data or self.video, content_type="video/mp4"),
                "amount": amount, "unit": unit,
            })

    def test_split_into_parts(self):
        r = self.upload(3, "s")
        job = VideoJob.objects.get()
        self.assertRedirects(r, reverse("splitter:detail", args=[job.pk]))
        self.assertEqual(job.status, VideoJob.DONE)
        self.assertEqual(job.parts.count(), 4)  # 10s / 3s -> 3+3+3+1
        self.assertAlmostEqual(job.parts.first().duration, 3, delta=0.6)
        self.assertEqual(job.segment_seconds, 3)

    def test_minutes_unit(self):
        self.upload(1, "m")
        job = VideoJob.objects.get()
        self.assertEqual(job.segment_seconds, 60)
        self.assertEqual(job.parts.count(), 1)

    def test_rejects_bad_extension_and_non_video(self):
        r = self.client.post(reverse("splitter:index"), {
            "video": SimpleUploadedFile("a.txt", b"hello"), "amount": 5, "unit": "s"})
        self.assertContains(r, "صيغة غير مدعومة")
        r = self.upload(5, "s", name="fake.mp4", data=b"not a video at all")
        self.assertContains(r, "تعذّرت قراءة الفيديو")
        self.assertEqual(VideoJob.objects.count(), 0)

    def test_too_many_parts_rejected(self):
        from unittest import mock
        with mock.patch("splitter.views.MAX_PARTS", 2):
            r = self.upload(3, "s")  # 10s / 3s = 4 parts > 2
        self.assertContains(r, "عدد الأجزاء")
        self.assertEqual(VideoJob.objects.count(), 0)

    def test_zip_and_privacy_and_delete(self):
        self.upload(5, "s")
        job = VideoJob.objects.get()
        z = self.client.get(reverse("splitter:zip", args=[job.pk]))
        self.assertEqual(z.status_code, 200)
        self.assertIn("zip", z["Content-Type"])

        other = User.objects.create_user("u2", "u2@test.dev", PW)
        self.client.force_login(other)
        self.assertEqual(self.client.get(reverse("splitter:detail", args=[job.pk])).status_code, 404)
        self.assertEqual(self.client.post(reverse("splitter:delete", args=[job.pk])).status_code, 404)

        self.client.force_login(self.user)
        parts_dir = job.parts_dir
        self.assertTrue(parts_dir.exists())
        self.client.post(reverse("splitter:delete", args=[job.pk]))
        self.assertFalse(VideoJob.objects.exists())
        self.assertFalse(parts_dir.exists())

    def test_stale_active_job_is_marked_failed(self):
        job = VideoJob.objects.create(user=self.user, title="x", source="splitter/x.mp4",
                                      segment_seconds=5, status=VideoJob.PROCESSING)
        self.client.get(reverse("splitter:detail", args=[job.pk]))
        job.refresh_from_db()
        self.assertEqual(job.status, VideoJob.FAILED)

    def test_login_required(self):
        self.client.logout()
        self.assertEqual(self.client.get(reverse("splitter:index")).status_code, 302)


@override_settings(MEDIA_ROOT=MEDIA)
class PartAccessTests(TestCase):
    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        if not services.tools_available():
            raise cls.skipTest(cls, "ffmpeg not installed")
        cls.video = make_video(6)

    def setUp(self):
        self.user = User.objects.create_user("o1", "o1@test.dev", PW)
        self.client.force_login(self.user)
        from unittest import mock
        with mock.patch.object(services, "start_job", side_effect=services.process_job):
            self.client.post(reverse("splitter:index"), {
                "video": SimpleUploadedFile("c.mp4", self.video, content_type="video/mp4"), "amount": 3, "unit": "s"})
        self.job = VideoJob.objects.get()

    def test_owner_gets_file_with_range_support(self):
        url = reverse("splitter:part", args=[self.job.pk, 1])
        full = self.client.get(url)
        self.assertEqual(full.status_code, 200)
        self.assertEqual(full["Accept-Ranges"], "bytes")
        r = self.client.get(url, HTTP_RANGE="bytes=0-99")
        self.assertEqual(r.status_code, 206)
        self.assertEqual(len(r.content), 100)
        self.assertEqual(self.client.get(url, HTTP_RANGE="bytes=999999999-").status_code, 416)

    def test_other_user_and_anonymous_blocked(self):
        url = reverse("splitter:part", args=[self.job.pk, 1])
        self.client.force_login(User.objects.create_user("o2", "o2@test.dev", PW))
        self.assertEqual(self.client.get(url).status_code, 404)
        self.client.logout()
        self.assertEqual(self.client.get(url).status_code, 302)

    def test_media_route_does_not_expose_videos(self):
        part = self.job.parts.first()
        self.assertEqual(self.client.get("/" + part.file.url.lstrip("/")).status_code, 404)
